using OcctSharp.ExchangeRoots;
using OcctSharp.Tests.Shared;
namespace OcctSharp.Runtime.Tests;
public sealed class ExchangeRootTests {
 [Fact]public void MixedStepRootsKeepValidOutputWithoutPublishingFailedRootTopology(){string path=Path.Combine(Path.GetTempPath(),"OcctSharp.BD.Mixed."+Guid.NewGuid()+".step");try{using(var box=ShapeFactory.CreateBox(2,3,4))using(var moved=box.Transformed(ShapeTransform.CreateTranslation(8,0,0)))using(var set=OcctSharp.CopiedCollections.OwnedShapeSet.Create(box,moved))using(var writer=OcctSharp.TransferRecords.WriterTransferSession.Create(set,OcctSharp.TransferRecords.WriterTransferFormat.Step)){Assert.True(writer.TransferAndWrite(path).WriteSucceeded);}string text=File.ReadAllText(path);var representation=System.Text.RegularExpressions.Regex.Match(text,@"ADVANCED_BREP_SHAPE_REPRESENTATION\s*\(\s*'[^']*'\s*,\s*\(([^)]*)\)",System.Text.RegularExpressions.RegexOptions.Singleline);Assert.True(representation.Success);string axis=System.Text.RegularExpressions.Regex.Matches(representation.Groups[1].Value,@"#\d+").Select(x=>x.Value).Single(id=>System.Text.RegularExpressions.Regex.IsMatch(text,System.Text.RegularExpressions.Regex.Escape(id)+@"\s*=\s*AXIS2_PLACEMENT_3D\s*\("));var group=representation.Groups[1];File.WriteAllText(path,text[..group.Index]+axis+text[(group.Index+group.Length)..]);using var workspace=ExchangeRootWorkspace.Open(path);var snapshot=workspace.Snapshot();Assert.Equal(2,snapshot.Roots.Count);using var result=workspace.Transfer(snapshot.Roots.Select(x=>x.Id));Assert.False(result.Completed);var failed=Assert.Single(result.Roots,x=>!x.Completed);Assert.Equal(0,failed.ShapeCount);var complete=Assert.Single(result.Roots,x=>x.Completed);Assert.Equal(1,complete.ShapeCount);Assert.Equal(1,result.ShapeCount);Assert.All(result.Roots,x=>Assert.NotNull(x.Checks));using var shape=result.GetShape(complete.FirstShapeIndex);Assert.True(shape.IsValid);Assert.Equal(6,shape.FaceCount);}finally{File.Delete(path);}}
 [Fact]public void RealEmptyStepRootKeepsFailureDiagnosticsAndPublishesNoShape(){string path=Fixture();try{string text=File.ReadAllText(path);var representation=System.Text.RegularExpressions.Regex.Match(text,@"ADVANCED_BREP_SHAPE_REPRESENTATION\s*\(\s*'[^']*'\s*,\s*\(([^)]*)\)",System.Text.RegularExpressions.RegexOptions.Singleline);Assert.True(representation.Success);var ids=System.Text.RegularExpressions.Regex.Matches(representation.Groups[1].Value,@"#\d+").Select(x=>x.Value).ToArray();string axis=ids.Single(id=>System.Text.RegularExpressions.Regex.IsMatch(text,System.Text.RegularExpressions.Regex.Escape(id)+@"\s*=\s*AXIS2_PLACEMENT_3D\s*\("));var group=representation.Groups[1];text=text[..group.Index]+axis+text[(group.Index+group.Length)..];File.WriteAllText(path,text);using var workspace=ExchangeRootWorkspace.Open(path);using var result=workspace.Transfer(workspace.Snapshot().Roots.Select(x=>x.Id));Assert.False(result.Completed);Assert.NotEmpty(result.Roots);Assert.Contains(result.Roots,x=>!x.Completed);Assert.All(result.Roots,x=>Assert.Equal(0,x.ShapeCount));Assert.Equal(0,result.ShapeCount);Assert.Throws<ArgumentOutOfRangeException>(()=>result.GetShape(0));Assert.Throws<InvalidOperationException>(()=>workspace.Transfer(workspace.Snapshot().Roots.Select(x=>x.Id)));}finally{File.Delete(path);}}
 static string Fixture(){string path=Path.Combine(Path.GetTempPath(),"OcctSharp.BD.Test."+Guid.NewGuid()+".step");using var box=ShapeFactory.CreateBox(2,3,4);ShapeExchange.WriteStep(box,path);return path;}
 [Fact]public void StepIgesPrivateConfigurationSelectionTransferExportAndIndependentReadback()=>BatchBDExchangeWorkflow.Run();
 [Theory][InlineData(RootTransferRoute.RootRank)][InlineData(RootTransferRoute.ModelNumber)][InlineData(RootTransferRoute.Entity)]public void AllSdkTransferRoutesPublishIndependentCompleteTopology(RootTransferRoute route){string path=Fixture();try{using var workspace=ExchangeRootWorkspace.Open(path);var root=workspace.Snapshot().Roots.Single();using var result=workspace.Transfer([root.Id],route);Assert.True(result.Completed);Assert.Single(result.Roots);Assert.True(result.Roots[0].NativeSucceeded);Assert.Equal(root.ModelNumber,result.Roots[0].ModelNumber);Assert.Equal(route,result.Route);using var first=result.GetShape(0);using var second=result.GetShape(0);result.Dispose();workspace.Dispose();Assert.True(first.IsValid);Assert.True(second.IsValid);Assert.False(first.IsSame(second));Assert.Equal(6,first.FaceCount);}finally{File.Delete(path);}}
 [Fact]public void ForeignWorkspaceAndDefaultRootsAreRejectedBeforeConsumingEpoch(){string path=Fixture();try{using var a=ExchangeRootWorkspace.Open(path);using var b=ExchangeRootWorkspace.Open(path);Assert.Throws<ArgumentException>(()=>a.Transfer([b.Snapshot().Roots.Single().Id]));Assert.Throws<ArgumentException>(()=>a.Transfer([default]));using var result=a.Transfer([a.Snapshot().Roots.Single().Id]);Assert.True(result.Completed);Assert.Throws<InvalidOperationException>(()=>a.Transfer([a.Snapshot().Roots.Single().Id]));}finally{File.Delete(path);}}
 [Fact]public void PrivateActorConfigurationDoesNotLeakToAnotherWorkspace(){string path=Fixture();try{using var a=ExchangeRootWorkspace.Open(path,options:new(2e-6,1e-7,1e-3));var before=a.Snapshot();using var b=ExchangeRootWorkspace.Open(path,options:new(8e-6,1e-7,1e-2));var second=b.Snapshot();using var other=b.Transfer([second.Roots.Single().Id]);Assert.True(other.Completed);var after=a.Snapshot();Assert.NotEqual(string.Join('|',before.PrivateRepairParameters),string.Join('|',second.PrivateRepairParameters));Assert.Equal(before.PrivateRepairParameters,after.PrivateRepairParameters);Assert.Contains(before.PrivateRepairParameters,p=>p.Key.EndsWith(".Tolerance3d",StringComparison.Ordinal)&&double.TryParse(p.Value,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out double actual)&&actual==2e-6);using var result=a.Transfer([before.Roots.Single().Id]);Assert.Equal(before.PrivateRepairParameters,result.PrivateRepairParameters);}finally{File.Delete(path);}}
 [Fact]public void ChangedSourceFileInvalidatesAllExistingRootIdentities(){string path=Fixture();try{using var workspace=ExchangeRootWorkspace.Open(path);var root=workspace.Snapshot().Roots.Single().Id;File.AppendAllText(path,"\n/* changed */\n");Assert.Throws<IOException>(()=>workspace.Snapshot());Assert.Throws<IOException>(()=>workspace.Transfer([root]));}finally{File.Delete(path);}}
 [Fact]public void InvalidToleranceOrderingAndFormatAreRejectedBeforeNativeRead(){Assert.Throws<ArgumentException>(()=>ExchangeRootWorkspace.Open("missing.step",options:new(1e-4,1e-3,.1)));Assert.Throws<ArgumentOutOfRangeException>(()=>ExchangeRootWorkspace.Open("missing.step",options:new(double.NaN)));Assert.Throws<ArgumentOutOfRangeException>(()=>ExchangeRootWorkspace.Open("missing.step",(RootExchangeFormat)9));}
 [Fact]public void LazySelectionBudgetIsBoundedAndDisposesTheEnumerator(){string path=Fixture();try{using var workspace=ExchangeRootWorkspace.Open(path);var root=workspace.Snapshot().Roots.Single().Id;bool disposed=false;int visits=0;IEnumerable<ExchangeRootId> Input(){try{while(true){visits++;yield return root;}}finally{disposed=true;}}Assert.Throws<ArgumentOutOfRangeException>(()=>workspace.Transfer(Input()));Assert.True(disposed);Assert.Equal(4097,visits);using var result=workspace.Transfer([root]);Assert.True(result.Completed);}finally{File.Delete(path);}}
 [Fact]public void DisposalKeepsDetachedDiagnosticsAndRejectsLiveQueries(){string path=Fixture();try{using var workspace=ExchangeRootWorkspace.Open(path);var data=workspace.Snapshot();using var result=workspace.Transfer([data.Roots.Single().Id]);var roots=result.Roots;result.Dispose();workspace.Dispose();Assert.Equal(64,data.Sha256.Length);Assert.True(roots.Single().Completed);Assert.Throws<ObjectDisposedException>(()=>workspace.Snapshot());Assert.Throws<ObjectDisposedException>(()=>result.GetShape(0));}finally{File.Delete(path);}}
 [Fact]public void CopiedOutputShapeIndicesAreStrictlyResultLocal(){string path=Fixture();try{using var workspace=ExchangeRootWorkspace.Open(path);using var result=workspace.Transfer([workspace.Snapshot().Roots.Single().Id]);Assert.Throws<ArgumentOutOfRangeException>(()=>result.GetShape(-1));Assert.Throws<ArgumentOutOfRangeException>(()=>result.GetShape(result.ShapeCount));}finally{File.Delete(path);}}
}
